pub fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    assert!(!a.is_empty(), "input array must be non-empty");
    assert!((0..=100).contains(&q), "q must be in [0, 100]");

    // Specification-required edge cases.
    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }

    // For intermediate quantiles, return a value within [min, max] by selecting
    // an order statistic. This is deterministic and satisfies the bounds.
    let mut sorted = a;
    sorted.sort();

    let n = sorted.len();
    // Map q in [1,99] to an index in [0, n-1].
    // Use integer arithmetic with floor.
    let idx = (q as usize * (n - 1)) / 100;

    sorted[idx]
}